import fs from "node:fs";
import path from "node:path";
import postgres from "postgres";
import { encode } from "@auth/core/jwt";

/**
 * E2E global setup — creates disposable authenticated states for the isolated
 * test environment.
 *
 * Safety contract:
 * - Runs ONLY against a localhost DATABASE_URL (refused otherwise).
 * - Signs the sessions with the throwaway E2E_AUTH_SECRET generated by
 *   scripts/run-e2e.cjs — never the real AUTH_SECRET.
 * - The emitted storage states live in playwright/.auth/ (gitignored). They
 *   must never be committed.
 * - Each user's rows are recreated from scratch on every run so tests see a
 *   brand-new learner.
 *
 * Two accounts are minted so the cross-device suite can prove account
 * isolation: a second, independent learner (state-b.json) must never restore
 * the first learner's private progress, while a second browser *context* on
 * the same learner (state.json) simulates a second *device* that legitimately
 * does restore it.
 */
const ACCOUNTS: Array<{ email: string; name: string; stateFile: string }> = [
  { email: "e2e-test@example.com", name: "E2E Test User", stateFile: "state.json" },
  {
    email: "e2e-test-b@example.com",
    name: "E2E Test User B",
    stateFile: "state-b.json",
  },
];

export default async function globalSetup() {
  const secret = process.env.E2E_AUTH_SECRET;
  const url = process.env.DATABASE_URL;
  if (!secret) throw new Error("E2E_AUTH_SECRET missing — run e2e via `npm run test:e2e`");
  if (!url) throw new Error("DATABASE_URL missing for e2e global setup");
  if (!/localhost|127\.0\.0\.1/.test(url)) {
    throw new Error("e2e global setup refuses to run against a non-localhost database");
  }

  const maxAge = 30 * 24 * 60 * 60;
  const now = Math.floor(Date.now() / 1000);
  const stateDir = path.join("playwright", ".auth");
  fs.mkdirSync(stateDir, { recursive: true });

  const sql = postgres(url, { connect_timeout: 10, prepare: false });
  try {
    for (const account of ACCOUNTS) {
      // Reset: FK cascades clean every user-scoped table for the disposable account.
      await sql`DELETE FROM users WHERE email = ${account.email}`;
      const inserted = await sql`
        INSERT INTO users (email, name) VALUES (${account.email}, ${account.name}) RETURNING id
      `;
      const userId = (inserted[0] as { id: string }).id;

      const jwt = await encode({
        token: {
          name: account.name,
          email: account.email,
          sub: userId,
          userId,
          picture: null,
          iat: now,
          exp: now + maxAge,
        },
        secret,
        salt: "authjs.session-token",
      });

      fs.writeFileSync(
        path.join(stateDir, account.stateFile),
        JSON.stringify({
          cookies: [
            {
              name: "authjs.session-token",
              value: jwt,
              domain: "localhost",
              path: "/",
              httpOnly: true,
              secure: false,
              sameSite: "Lax" as const,
              expires: now + maxAge,
            },
          ],
          origins: [],
        })
      );
      console.log(
        `e2e auth state written for disposable user ${userId} -> ${account.stateFile} (localhost only)`
      );
    }
  } finally {
    await sql.end({ timeout: 5 }).catch(() => {});
  }
}
